import time
from slow import count_primes
def ref(n):
    if n < 3: return 0
    s = bytearray([1]) * n; s[0] = s[1] = 0
    for i in range(2, int(n**0.5) + 1):
        if s[i]: s[i*i::i] = bytearray(len(range(i*i, n, i)))
    return sum(s)
for n in list(range(0, 60)) + [97, 98, 100, 101, 1000, 1009, 7919, 7920]:
    assert count_primes(n) == ref(n), (n, count_primes(n))
t = time.time()
assert count_primes(200000) == ref(200000)
assert time.time() - t < 6, "too slow"
print("ok")
